            current_max = max(coins)
            current_avg = sum(coins)/len(coins)
            current_len = len(coins)

            if current_max > best_max:
                best_max = current_max
                best_candidates = [(current_avg, current_len, bag_index)]
            elif current_max == best_max:
                best_candidates.append((current_avg, current_len, bag_index))

        if best_candidates:
            sorted_candidates = sorted(best_candidates, key=lambda x: (-x[0], -x[1], x[2]))
            chosen_bag = sorted_candidates[0][2]
        else:
            # Fallback to first non-empty bag if no candidates (unlikely)
            for bag_index in range(len(random_bag)):
                if bag_index not in empty_bags and random_bag[bag_index]:
                    chosen_bag = bag_index
                    break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_bag, type='custom')]
        )

